The following Terraform configuration deploys:

- An AWS Lightsail Linux instance
- A managed AWS Lightsail MySQL database
- Public SSH access on port `22`
- A startup script on the instance that installs a MySQL client and writes database connection details to `/home/ec2-user/db_connection_info.txt`
- Outputs for the instance IP address and database endpoint

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where Lightsail resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance."
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "mysql-app-lightsail-instance"
}

variable "database_name" {
  description = "Name of the Lightsail MySQL database resource."
  type        = string
  default     = "mysql-lightsail-database"
}

